mapper.select:
SELECT mdr.id, mdr.audit_status, mdr.audit_man_day, mdr.reject_reason, mdr.auditor, mdr.auditor_id, mdr.create_date, mdr.create_man, mdr.create_man_id,mdr.reportor,mdr.reportor_id, mdr.man_day_desc, md.week_start_date, md.week_end_date, p.name projectName FROM
man_day_report mdr
(select * from (select * from (select * from (select id,man_day_id, audit_status,audit_man_day, reject_reason,auditor, auditor_id, man_day_desc create_date,create_man, create_man_id,reportor,reportor_id, case when audit_status=20 then 3 when audit_status=0 then 2 when audit_status=10 then 1 end as status from man_day_report mdr
order by id desc)a group by man_day_id,audit_status) b order by status desc) c group by man_day_id) mdr
LEFT JOIN man_day md on mdr.man_day_id = md.id LEFT JOIN project p on md.project_id = p.id
AND p.name like concat('%',#{projectName},'%') AND mdr.reject_reason like concat('%',#{rejectReason},'%')
AND mdr.audit_status in
#{item}
AND md.week_start_date = #{weekStartDate}
/*keep orderby*/

SELECT * FROM man_day_report WHERE id in
#{item}
AND is_deleted = false

SELECT * FROM man_day_report mdr INNER JOIN (SELECT max(id) id FROM man_day_report GROUP BY man_day_id) tmdr ON mdr.id = tmdr.id WHERE man_day_id IN
#{item}
AND is_deleted = false

SELECT *
FROM man_day_report
WHERE man_day_id = #{manDayId}
  AND audit_status = #{auditStatus}
  AND is_deleted = false
